create table public.ai_identity_sections (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title text not null,
  body text not null,
  ordinal integer not null default 100,
  layer integer not null default 1,
  enabled boolean not null default true,
  notes text,
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

grant select on public.ai_identity_sections to anon;
grant select on public.ai_identity_sections to authenticated;
grant all on public.ai_identity_sections to service_role;

alter table public.ai_identity_sections enable row level security;

create policy "enabled identity sections readable" on public.ai_identity_sections
  for select to anon, authenticated using (enabled = true);

create policy "admins manage identity sections" on public.ai_identity_sections
  for all to authenticated using (public.has_role(auth.uid(),'admin'))
  with check (public.has_role(auth.uid(),'admin'));

create trigger ai_identity_sections_touch before update on public.ai_identity_sections
  for each row execute function public.touch_updated_at();

create index ai_identity_sections_order_idx on public.ai_identity_sections (enabled, ordinal);

